# -*- coding: utf-8 -*-
"""
只读探测（需求1）：ERP「筛选模板 = 未取消等待发货」与「渠道筛选」的交互。
核心要回答：**选渠道后再选筛选模板，会不会把渠道筛选重置掉？**（截图里包裹数 2->5、
渠道 chip 疑消失 => 若真重置，则在主流程里选模板前必须做保护，否则会全量误下单。）

步骤（全程只筛选/读计数，绝不点『物流下单』）：
  1. 复用 profile 会话（需先 python capture/erp_manual_login.py 登录）。
  2. 进 待处理，逐个渠道试筛，挑第一个有单的渠道。
  3. 记录：筛渠道后 快照A（包裹数/chips/渠道输入框值/vxe行数）。
  4. dump「筛选模板」弹层结构（模板名称元素/选择器）。
  5. 选中「未取消等待发货」，记录 快照B。
  6. 对比 A/B 判断渠道筛选是否被重置。
输出 UTF-8：capture/dumps/erp_probe_template.txt
用法：python capture/erp_probe_template.py
"""
import sys, os, time
sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
import config
config.DRY_RUN = True          # 双保险：绝不真下单
import core, erp
from rules import CHANNEL_ORDER
from playwright.sync_api import sync_playwright

out = []
def w(s=""):
    out.append(str(s))
    try: print(s)
    except Exception: pass


def snapshot(page):
    """读顶部包裹计数/筛选 chip/渠道输入框值/vxe 逻辑行数，判断当前筛选状态。"""
    snap = page.evaluate(r"""() => {
      const txt = e => (e.innerText||'').trim();
      // 所有包裹(N)
      let pkg='';
      document.querySelectorAll('*').forEach(e=>{ if(e.children.length) return;
        const m=txt(e).match(/所有包裹\s*\((\d+)\)/); if(m) pkg=m[1]; });
      // 筛选 chip（el-tag 之类）
      const chips=[...document.querySelectorAll('.el-tag, .filter-tag, [class*=tag-item], [class*=filter-item]')]
        .map(txt).filter(s=>s && s.length<40);
      // 渠道输入框当前值（filter_by_channel 用的就是这个）
      const chan=[...document.querySelectorAll("input[placeholder*='渠道']")].map(i=>i.value||'');
      return {pkg, chips:[...new Set(chips)], channelInputs: chan};
    }""")
    snap["vxe_rows"] = erp.count_orders(page)
    return snap


def dump_template_popover(page):
    """点开『筛选模板』后 dump 弹层里可点的模板名称元素（标签/类/文本）。"""
    info = page.evaluate(r"""() => {
      const roots=[...document.querySelectorAll('.el-popper, .el-popover, .el-dropdown-menu, [class*=popper]')]
        .filter(e=>e.offsetParent!==null);
      const items=[];
      roots.forEach(r=>{
        r.querySelectorAll('*').forEach(e=>{
          if(e.children.length) return;                 // 只取叶子文本节点
          const t=(e.innerText||'').trim();
          if(t && t.length<30) items.push({tag:e.tagName, cls:e.className, text:t});
        });
      });
      return {popper_count: roots.length, items};
    }""")
    return info


def main():
    with sync_playwright() as p:
        ctx = core.open_context(p)
        page = ctx.pages[0] if ctx.pages else ctx.new_page()
        try:
            if not core.ensure_erp(page):
                w("!! ERP 会话失效，请先： python capture/erp_manual_login.py 登录后再跑本探测")
                return

            # 找一个有单的渠道
            picked = None
            for ch in CHANNEL_ORDER:
                erp.open_order_ship(page)
                if not erp.goto_view(page, "待处理"):
                    continue
                if not erp.filter_by_channel(page, ch):
                    w(f"渠道 {ch} 筛选失败，跳过")
                    continue
                n = erp.count_orders(page)
                w(f"渠道 {ch} -> 待处理 {n} 条")
                if n and n > 0:
                    picked = ch
                    break
            if not picked:
                w("!! 所有渠道当前都无待处理单，换有单时再跑本探测")
                return

            w(f"\n=== 选定测试渠道: {picked} ===")
            snapA = snapshot(page)
            w(f"[快照A 选渠道后]  {snapA}")

            w("\n--- 打开『筛选模板』弹层，dump 结构 ---")
            opened = False
            for sel in ("text=筛选模板", ":text('筛选模板')"):
                try:
                    page.click(sel, timeout=4000); opened = True; break
                except Exception:
                    continue
            if not opened:
                w("!! 未找到『筛选模板』触发控件（选择器需调整）")
                return
            time.sleep(1.5)
            w(f"弹层结构 = {dump_template_popover(page)}")

            w("\n--- 选中『未取消等待发货』 ---")
            picked_tpl = False
            for el in page.query_selector_all(".el-popper:visible *, .el-popover:visible *, .el-dropdown-menu:visible *"):
                try:
                    if el.is_visible() and (el.inner_text() or "").strip() == erp.FILTER_TEMPLATE:
                        el.click(); picked_tpl = True; break
                except Exception:
                    continue
            w(f"选中模板 = {picked_tpl}")
            time.sleep(2.5)

            snapB = snapshot(page)
            w(f"[快照B 选模板后]  {snapB}  模板chip={template_chips(page)}")

            # ---- Phase3：模板之后再筛渠道，看能否『模板∩渠道』并存 ----
            w(f"\n--- Phase3：选模板后再筛渠道 {picked} ---")
            re_ok = erp.filter_by_channel(page, picked)
            time.sleep(2)
            snapC = snapshot(page)
            w(f"[快照C 模板后再筛渠道]  再筛渠道成功={re_ok}  {snapC}  模板chip={template_chips(page)}")

            w("\n=== 结论 ===")
            w(f"vxe行数  A(仅渠道)={snapA.get('vxe_rows')}  ->  B(仅模板/重置渠道)={snapB.get('vxe_rows')}"
              f"  ->  C(模板后再筛渠道)={snapC.get('vxe_rows')}")
            reset_by_template = (snapB.get("vxe_rows") or 0) > (snapA.get("vxe_rows") or 0)
            channel_narrows_back = (snapC.get("vxe_rows") or 99) <= (snapA.get("vxe_rows") or 0)
            tpl_survive = len(template_chips(page)) > 0
            w(f"① 选模板是否重置渠道 = {reset_by_template}  "
              + ("（B行数>A，渠道被重置）" if reset_by_template else "（未见重置）"))
            w(f"② 模板后再筛渠道能否收回到渠道范围 = {channel_narrows_back}  (C行数≈A)")
            w(f"③ 再筛渠道后模板条件是否仍在 = {tpl_survive}  chip={template_chips(page)}")
            if reset_by_template and channel_narrows_back and tpl_survive:
                w("=> 方案：主流程用【先选模板→再筛渠道】即可 模板∩渠道 并存且安全。")
            elif reset_by_template and channel_narrows_back:
                w("=> 再筛渠道会清掉模板：只能二选一。渠道是安全底线优先，模板效果需另想办法（如用更多筛选逐条件）。")
            else:
                w("=> 交互异常，需人工再看截图/dump。")
        finally:
            try: ctx.close()
            except Exception: pass

    path = os.path.join(config.DUMP_DIR, "erp_probe_template.txt")
    with open(path, "w", encoding="utf-8") as f:
        f.write("\n".join(out))
    print("WROTE", path)


if __name__ == "__main__":
    main()

